mapper.select:
SELECT tpd.id AS detailId, tpd.treat_plan_id AS planId, tpd.treat_step_id AS stepId, tpd.type, tpd.tooth_bit AS toothBit, tpd.billing_item_id AS billingItemId, tpd.billing_item_name AS billingItemName, tpd.unit, tpd.price, tpd.price*tpd.quantity AS memberPrice, tpd.quantity, IFNULL(tpdw.writeoffQuantity, 0) AS writeoffQuantity, tpd.quantity-IFNULL(tpdw.writeoffQuantity, 0) AS enableQuantity, CASE WHEN tpdw.status IS NULL OR IFNULL(tpdw.writeoffQuantity,0) <= 0 OR tpdw.status = 0 THEN 1
WHEN tpr.status = 4 THEN 4
WHEN IFNULL(tpdw.writeoffQuantity, 0) < tpd.quantity and tpdw.status = 1 THEN 2 WHEN IFNULL(tpdw.writeoffQuantity, 0) = tpd.quantity and tpdw.status = 1 THEN 3 END AS status, tpd.remark, tpd.crt_id AS crtId, tpd.crt_time AS crtTime, tpd.upt_id AS uptId, tpd.upt_time AS uptTime FROM treat_plan_detail tpd LEFT JOIN ( SELECT IFNULL(SUM(write_off_quantity),0) writeoffQuantity, IFNULL(status,0) AS status, plan_detail_id FROM treat_plan_detail_writeoff GROUP BY plan_detail_id ) tpdw ON tpd.id = tpdw.plan_detail_id
LEFT JOIN treat_plan_record tpr ON tpr.id = tpd.treat_plan_id
AND tpd.treat_plan_id = #{query.treatPlanId}
AND tpd.treat_step_id = #{query.treatStepId}
